// RigNotificationUpdateValidator is the rules for changing one that already
// exists: what the schema cannot express.
//
// One optional function per field this operation can set, so the set of fields
// is the set of rules that could apply — a column an update cannot touch has
// no hook here to write by mistake. A nil one is skipped. Every configured
// hook runs, because a rule that fails should not hide the next one, so a
// request reports everything wrong with it.
//
// A hook returns a FieldError to attach the message to a specific field, or
// any other error to fail the request outright.
type RigNotificationUpdateValidator struct {
	// What happened, as the application names it. Narrow it to an enum of your own
	// to get a switch the compiler can see.
	Kind func(ctx context.Context, c *RigNotificationValidatorContext, value string) error
	// Resolved means the audience was determined and the inbox lines exist. It
	// does not mean anything was sent.
	State func(ctx context.Context, c *RigNotificationValidatorContext, value RigNotificationState) error
	// When this is due. now() is the ordinary case; a scheduled notification is
	// the same row with a later time, which is the only difference between the
	// two.
	DeliverAt func(ctx context.Context, c *RigNotificationValidatorContext, value time.Time) error
	// When the audience was computed. Null while the notification is still pending
	// or was cancelled.
	ResolvedAt func(ctx context.Context, c *RigNotificationValidatorContext, value *time.Time) error
	// What a template needs beyond the linked row. Give it a Go type with the
	// go_type key if it has a shape.
	Payload func(ctx context.Context, c *RigNotificationValidatorContext, value json.RawMessage) error
	// What collapses several of these into one inbox line, decided when the
	// announcement was written and copied onto the line when the audience is
	// resolved.
	GroupKey func(ctx context.Context, c *RigNotificationValidatorContext, value *string) error
	// A recipient list captured at write time, and the one exception to computing
	// the audience late. Null is the ordinary case; a list here skips the question
	// entirely, for an audience that genuinely cannot be re-derived.
	AccountIds func(ctx context.Context, c *RigNotificationValidatorContext, value []uuid.UUID) error
	// When a dispatcher took this to resolve. Past notifications.claim_ttl another
	// may, which is what makes a crashed process recoverable.
	ClaimedAt func(ctx context.Context, c *RigNotificationValidatorContext, value *time.Time) error
	// Which process holds the lease, so a stuck one traces to a pod rather than to
	// a mystery.
	ClaimedBy func(ctx context.Context, c *RigNotificationValidatorContext, value *uuid.UUID) error
	// How many times resolving this has been attempted.
	Attempts func(ctx context.Context, c *RigNotificationValidatorContext, value int) error

	// Entity runs after the per-field hooks, for a rule that is about the row
	// rather than about one column.
	Entity func(ctx context.Context, c *RigNotificationValidatorContext) error
}

// RunUpdate implements [dbhook.UpdateValidator]: it runs the service's rules
// against the row this update would produce, with the row as it was available
// for a rule about the change itself.
func (v RigNotificationUpdateValidator) RunUpdate(ctx context.Context, claims tenancy.Claims, i *RigNotificationUpdateInput, prev *RigNotification) error {
	c := &RigNotificationValidatorContext{
		Values:   i.Merged(prev),
		Claims:   claims,
		previous: *prev,
		isUpdate: true,
		changed:  map[string]bool{},
	}
	c.changed[ColumnRigNotificationKind] = i.Kind.IsSet()
	c.changed[ColumnRigNotificationState] = i.State.IsSet()
	c.changed[ColumnRigNotificationDeliverAt] = i.DeliverAt.IsSet()
	c.changed[ColumnRigNotificationResolvedAt] = i.ResolvedAt.Touched()
	c.changed[ColumnRigNotificationPayload] = i.Payload.IsSet()
	c.changed[ColumnRigNotificationGroupKey] = i.GroupKey.Touched()
	c.changed[ColumnRigNotificationAccountIds] = i.AccountIds.Touched()
	c.changed[ColumnRigNotificationClaimedAt] = i.ClaimedAt.Touched()
	c.changed[ColumnRigNotificationClaimedBy] = i.ClaimedBy.Touched()
	c.changed[ColumnRigNotificationAttempts] = i.Attempts.IsSet()

	failed, err := v.run(ctx, c)
	if err != nil {
		return err
	}
	if failed != nil {
		return failed
	}
	return nil
}

